function reformatDate(date: string): string {
    const s = date.split(' ');
    const months = ' JanFebMarAprMayJunJulAugSepOctNovDec';
    const day = parseInt(s[0].substring(0, s[0].length - 2));
    const month = Math.floor(months.indexOf(s[1]) / 3) + 1;
    return `${s[2]}-${month.toString().padStart(2, '0')}-${day.toString().padStart(2, '0')}`;
}

class Solution {
    /**
     * @param String $date
     * @return String
     */
    function reformatDate($date) {
        $arr = explode(' ', $date);
        $months = [
            'Jan' => '01',
            'Feb' => '02',
            'Mar' => '03',
            'Apr' => '04',
            'May' => '05',
            'Jun' => '06',
            'Jul' => '07',
            'Aug' => '08',
            'Sep' => '09',
            'Oct' => '10',
            'Nov' => '11',
            'Dec' => '12',
        ];
        $year = $arr[2];
        $month = $months[$arr[1]];
        $day = intval($arr[0]);
        if ($day > 0 && $day < 10) {
            $day = '0' . $day;
        }
        return $year . '-' . $month . '-' . $day;
    }
}

class Solution:
    def reformatDate(self, date: str) -> str:
        months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
        mapper = {v: str(k + 1) for k, v in enumerate(months)}
        split = date.split(' ')
        year = split[2]
        month = mapper.get(split[1])
        day = split[0][:len(split[0]) - 2]
        return year + '-' + month.zfill(2) + '-' + day.zfill(2)

class Solution {
    public String reformatDate(String date) {
        Map<String, Integer> mapper = new HashMap<>();
        String[] months = {"Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"};
        for (int i = 0; i < months.length; ++i) {
            mapper.put(months[i], i + 1);
        }
        String[] split = date.split(" ");
        int year = Integer.parseInt(split[2]);
        int month = mapper.get(split[1]);
        int day = Integer.parseInt(split[0].substring(0, split[0].length() -2));
        return String.format("%d-%02d-%02d", year, month, day);
    }
}

//Editorial: Just map the months to their numbers and append it to the solution.
class Solution {
public:
    string reformatDate(string date) {
        unordered_map<string,string> ump={{"Jan", "01"}, {"Feb", "02"}, {"Mar", "03"}, {"Apr", "04"}, {"May", "05"}, {"Jun", "06"}, {"Jul", "07"}, {"Aug", "08"}, {"Sep", "09"}, {"Oct", "10"}, {"Nov", "11"}, {"Dec", "12"}};
        int n=date.size();
        string ans="";
        // int day;
        if(n==13)
            ans+=date.substr(9,4);
        else
            ans+=date.substr(8,4);
        ans+='-';
        string month=(n==13)?date.substr(5,3):date.substr(4,3);
        ans+=(ump[month]);
        ans+='-';
        int day=(n==13)?stoi(date.substr(0,2)):stoi(date.substr(0,1));
        if(day<10)
            ans+=(to_string(0)+to_string(day));
        else
            ans+=to_string(day);
        return ans;
    }
};
